from pathlib import Path

path = Path('runtime/user_data/strategies/CompressionBreakout250.py')
s = path.read_text(encoding='utf-8')

s = s.replace(
    '"""Long-only multi-timeframe volatility breakout for the 250 USDT testbot.\n\n'
    'The strategy keeps the existing safety envelope, but requires a stronger market\n'
    'regime and a fresh compression/expansion sequence before a 15-minute breakout\n'
    'can enter. Higher timeframes are informative only; all entry signals are still\n'
    'created from closed 15-minute candles.\n"""',
    '"""Long-only 4h trend-pullback strategy for the 250 USDT testbot.\n\n'
    'V9 is a second pre-registered structural hypothesis: instead of buying a fresh\n'
    'high, it waits for a 4-hour pullback toward EMA50 inside a mature EMA50/EMA200\n'
    'uptrend and enters only after a closed 4h reclaim. 15m remains the execution\n'
    'timeframe and all signals are causal.\n"""',
)
s = s.replace(
    '    """15m ATR-normalized breakout with 1h/4h regime confirmation."""',
    '    """4h EMA50 pullback/reclaim inside mature multi-timeframe uptrends."""',
)

start = s.index('    # Research parameters remain intentionally narrow')
end = s.index('    plot_config: ClassVar', start)
params = '''    buy_pullback_atr = DecimalParameter(\n        0.00, 1.00, default=0.35, decimals=2, space="buy", optimize=True, load=True\n    )\n    buy_momentum_30d = DecimalParameter(\n        -0.05, 0.20, default=0.02, decimals=2, space="buy", optimize=True, load=True\n    )\n    buy_adx_4h_min = IntParameter(\n        12, 32, default=16, space="buy", optimize=True, load=True\n    )\n    buy_atr_min = DecimalParameter(\n        0.002, 0.020, default=0.003, decimals=3, space="buy", optimize=True, load=True\n    )\n    buy_atr_max = DecimalParameter(\n        0.020, 0.080, default=0.060, decimals=3, space="buy", optimize=True, load=True\n    )\n\n'''
s = s[:start] + params + s[end:]

ps=s.index('    plot_config: ClassVar'); pe=s.index('    @staticmethod\n    def _runmode_value',ps)
s=s[:ps]+'''    plot_config: ClassVar[dict[str, Any]] = {\n        "main_plot": {"ema_exec": {}, "ema_fast": {}},\n        "subplots": {"Momentum": {"rsi": {}}, "Volume": {"volume_ratio": {}}},\n    }\n\n'''+s[pe:]

st=s.index('    @informative("1h")'); en=s.index('    def custom_stake_amount(',st)
logic='''    @informative("1h")\n    def populate_indicators_1h(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        del metadata\n        dataframe["ema_fast"] = ta.EMA(dataframe, timeperiod=50)\n        dataframe["ema_slow"] = ta.EMA(dataframe, timeperiod=200)\n        dataframe["rsi"] = ta.RSI(dataframe, timeperiod=14)\n        dataframe["ema_fast_rising"] = (dataframe["ema_fast"] > dataframe["ema_fast"].shift(8)).astype(int)\n        return dataframe\n\n    @informative("4h")\n    def populate_indicators_4h(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        del metadata\n        dataframe["ema_fast"] = ta.EMA(dataframe, timeperiod=50)\n        dataframe["ema_exit"] = ta.EMA(dataframe, timeperiod=100)\n        dataframe["ema_slow"] = ta.EMA(dataframe, timeperiod=200)\n        dataframe["atr"] = ta.ATR(dataframe, timeperiod=14)\n        dataframe["rsi"] = ta.RSI(dataframe, timeperiod=14)\n        dataframe["adx"] = ta.ADX(dataframe, timeperiod=14)\n        dataframe["momentum_30d"] = dataframe["close"] / dataframe["close"].shift(180) - 1.0\n        dataframe["ema_fast_rising"] = (dataframe["ema_fast"] > dataframe["ema_fast"].shift(3)).astype(int)\n        prior_touch = dataframe["low"].shift(1) <= (dataframe["ema_fast"].shift(1) + self.buy_pullback_atr.value * dataframe["atr"].shift(1))\n        prior_above_slow = dataframe["low"].shift(1) > dataframe["ema_slow"].shift(1)\n        reclaim = (dataframe["close"] > dataframe["ema_fast"]) & (dataframe["close"] > dataframe["close"].shift(1))\n        dataframe["fresh_reclaim"] = (prior_touch & prior_above_slow & reclaim).astype(int)\n        return dataframe\n\n    @informative("4h", "BTC/{stake}", fmt="{base}_{column}_{timeframe}")\n    def populate_indicators_btc_4h(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        del metadata\n        dataframe["ema_fast"] = ta.EMA(dataframe, timeperiod=50)\n        dataframe["ema_slow"] = ta.EMA(dataframe, timeperiod=200)\n        dataframe["rsi"] = ta.RSI(dataframe, timeperiod=14)\n        dataframe["momentum_30d"] = dataframe["close"] / dataframe["close"].shift(180) - 1.0\n        dataframe["ema_fast_rising"] = (dataframe["ema_fast"] > dataframe["ema_fast"].shift(3)).astype(int)\n        return dataframe\n\n    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        del metadata\n        dataframe["ema_exec"] = ta.EMA(dataframe, timeperiod=20)\n        dataframe["ema_fast"] = ta.EMA(dataframe, timeperiod=50)\n        dataframe["atr"] = ta.ATR(dataframe, timeperiod=14)\n        dataframe["atr_pct"] = dataframe["atr"] / dataframe["close"]\n        dataframe["rsi"] = ta.RSI(dataframe, timeperiod=14)\n        dataframe["volume_mean"] = dataframe["volume"].shift(1).rolling(20, min_periods=20).mean()\n        dataframe["volume_ratio"] = dataframe["volume"] / dataframe["volume_mean"]\n        return dataframe\n\n    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        pair = str(metadata.get("pair", ""))\n        fresh = (dataframe["fresh_reclaim_4h"] > 0) & (dataframe["fresh_reclaim_4h"].shift(1).fillna(0) <= 0)\n        trend4 = (\n            fresh\n            & (dataframe["ema_fast_4h"] > dataframe["ema_exit_4h"])\n            & (dataframe["ema_exit_4h"] > dataframe["ema_slow_4h"])\n            & (dataframe["ema_fast_rising_4h"] > 0)\n            & (dataframe["adx_4h"] >= self.buy_adx_4h_min.value)\n            & (dataframe["momentum_30d_4h"] >= self.buy_momentum_30d.value)\n            & (dataframe["rsi_4h"] >= 48) & (dataframe["rsi_4h"] <= 72)\n        )\n        trend1 = (\n            (dataframe["close_1h"] > dataframe["ema_fast_1h"])\n            & (dataframe["ema_fast_1h"] > dataframe["ema_slow_1h"])\n            & (dataframe["ema_fast_rising_1h"] > 0)\n            & (dataframe["rsi_1h"] >= 48)\n        )\n        btc_up = (\n            (dataframe["btc_close_4h"] > dataframe["btc_ema_fast_4h"])\n            & (dataframe["btc_ema_fast_4h"] > dataframe["btc_ema_slow_4h"])\n            & (dataframe["btc_ema_fast_rising_4h"] > 0)\n            & (dataframe["btc_momentum_30d_4h"] > 0.0)\n        )\n        if pair != "BTC/USDT": trend4 = trend4 & btc_up\n        exec_ok = (\n            (dataframe["close"] > dataframe["ema_exec"])\n            & (dataframe["ema_exec"] > dataframe["ema_fast"])\n            & (dataframe["rsi"] >= 48) & (dataframe["rsi"] <= 76)\n            & (dataframe["atr_pct"] >= self.buy_atr_min.value)\n            & (dataframe["atr_pct"] <= self.buy_atr_max.value)\n            & (dataframe["volume_ratio"] >= 0.60) & (dataframe["volume"] > 0)\n        )\n        dataframe.loc[trend4 & trend1 & exec_ok, ["enter_long", "enter_tag"]] = (1, "slow_4h_pullback_reclaim")\n        return dataframe\n\n    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:\n        del metadata\n        exit_signal = (dataframe["close_4h"] < dataframe["ema_exit_4h"]) | (dataframe["momentum_30d_4h"] < -0.05)\n        dataframe.loc[exit_signal & (dataframe["volume"] > 0), ["exit_long", "exit_tag"]] = (1, "slow_pullback_trend_exit")\n        return dataframe\n\n'''
s=s[:st]+logic+s[en:]
path.write_text(s,encoding='utf-8')
